const dark = context.grafana?.theme?.isDark !== false;
const text = dark ? '#ccccdc' : '#24292e';
const frames = context.panel.data.series || [];
// One object per sample: its labels (time series frames) or string columns (table frames) plus `value`.
const rows = (f) => {
  const num = f.fields.find((x) => x.type === 'number');
  if (!num) return [];
  const dims = f.fields.filter((x) => x.type === 'string');
  const vals = Array.from(num.values);
  return vals.map((v, i) => {
    const r = { ...(num.labels || {}), value: Number(v) };
    dims.forEach((d) => (r[d.name] = d.values[i]));
    return r;
  });
};
const isNames = (f) => f.fields.some((x) => x.name === 'name');
const names = {};
frames.filter(isNames).flatMap(rows).forEach((r) => (names[r.vmid] = r.name));
const data = frames.filter((f) => !isNames(f)).flatMap(rows).filter((r) => r.value > 0);
const appName = (r) => (r.consumer === 'proxmox' && names[r.app] ? names[r.app] + ' (' + r.app + ')' : r.app);
const iec = (v) => {
  const u = ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'];
  let i = 0;
  while (v >= 1024 && i < u.length - 1) { v /= 1024; i++; }
  return v.toFixed(i ? 1 : 0) + ' ' + u[i];
};
// Nests the rows by the keys of `path(row)`; a parent's value is the sum of its children (ECharts does that).
const nest = (path) => {
  const root = new Map();
  data.forEach((r) => {
    let level = root;
    path(r).forEach((k, i, p) => {
      if (!level.has(k)) level.set(k, { value: 0, kids: new Map() });
      const n = level.get(k);
      if (i === p.length - 1) n.value += r.value;
      level = n.kids;
    });
  });
  const out = (m) => [...m].map(([name, n]) => (n.kids.size ? { name, children: out(n.kids) } : { name, value: n.value }));
  const total = (n) => (n.children ? n.children.reduce((s, c) => s + total(c), 0) : n.value);
  const sorted = (arr) => arr.map((n) => (n.children ? { ...n, children: sorted(n.children) } : n)).sort((a, b) => total(b) - total(a));
  return sorted(out(root));
};
const tip = { formatter: (p) => p.treePathInfo.slice(1).map((n) => n.name).join(' / ') + '<br/><b>' + iec(p.value) + '</b> raw' };

// k8s-static leaves share their PVC name (one PV can cover many walked directories): show the path.
const tree = nest((r) => [r.device_class, r.pool, r.consumer, appName(r), r.consumer === 'k8s-static' ? r.item : r.volume, r.kind]);
return {
  backgroundColor: 'transparent',
  tooltip: tip,
  series: [{
    type: 'treemap',
    data: tree,
    left: 0, right: 0, top: 0, bottom: 28,
    roam: false,
    leafDepth: 2, // two levels at a time; a click drills down, the breadcrumb goes back
    nodeClick: 'zoomToNode',
    breadcrumb: { show: true, bottom: 0, height: 24, itemStyle: { color: dark ? '#2a2d36' : '#e8e8ee', textStyle: { color: text } } },
    upperLabel: { show: true, height: 22, color: '#fff', formatter: (p) => p.name + '  ' + iec(p.value) },
    label: { show: true, color: '#fff', overflow: 'truncate', formatter: (p) => p.name + '\n' + iec(p.value) },
    itemStyle: { borderColor: dark ? '#181b1f' : '#fff', borderWidth: 1, gapWidth: 1 },
    levels: [
      { itemStyle: { borderWidth: 0, gapWidth: 4 } },
      { colorSaturation: [0.35, 0.6], itemStyle: { borderColorSaturation: 0.7, gapWidth: 3, borderWidth: 2 } },
      { colorSaturation: [0.35, 0.55], itemStyle: { borderColorSaturation: 0.65, gapWidth: 2, borderWidth: 2 } },
      { colorSaturation: [0.3, 0.5], itemStyle: { gapWidth: 1 } },
      { colorSaturation: [0.3, 0.5], itemStyle: { gapWidth: 1 } },
      { colorSaturation: [0.3, 0.5], itemStyle: { gapWidth: 1 } },
    ],
  }],
};

